with open(os.path.join(LOG_DIR, 'opencode-session.jsonl'), 'w', encoding='utf-8') as f:
    for id_, typ, seq, tc, tu, data in rows:
        d = json.loads(data)
        if typ == 'assistant':
            # Keep the chat and tool-call inputs; drop bulky tool output bodies.
            parts = []
            for part in d.get('content', []):
                if part.get('type') == 'text' and part.get('text'):
                    parts.append({'type': 'text', 'text': part['text']})
                elif part.get('type') == 'tool':
                    parts.append({
                        'type': 'tool',
                        'name': part.get('name'),
                        'input': part.get('state', {}).get('input', {}),
                    })
            d = {'time': d.get('time'), 'agent': d.get('agent'), 'model': d.get('model'), 'content': parts}
        elif typ == 'user':
            d = {'text': d.get('text') or d.get('metadata', {}).get('displayText', '')}
        f.write(json.dumps({
            'id': id_, 'type': typ, 'seq': seq,
            'time_created': tc, 'time_updated': tu,
            'data': d,
        }, ensure_ascii=False) + '\n')
